// GET /api/v1/projects — v2 project list (contract E-02, P01).
// POST /api/v1/projects — independent project creation (contract E-03, P05).
//
// Filters `?estado&cliente_id&linea_id&municipio_id&responsable_id`; any
// authenticated user may call it, but the rows are narrowed by the project
// read scope in `src/lib/api/projects.ts` (`canViewPortfolio` today, with the
// membership axis arriving in S2.6) — never by a role list declared here.
//
// POST creates an `INDEPENDIENTE` project (`oportunidad_id` null) with an
// autogenerated `PRY-AAAA-NNN` code: creation, both N..N join sets and the
// CREAR audit row run in ONE transaction (ADR-05, REQ-AUD-03). The GANADA
// conversion (E-05) lives in the clients route and reuses the schema exported
// here.
//
// No pagination: E-02 returns `{ proyectos: ProjectItemV2[] }`.

import { NextResponse } from "next/server";
import { EstadoProyecto } from "@prisma/client";
import { z } from "zod";
import { db } from "@/lib/db";
import { apiError, parseJsonBody } from "@/lib/api/errors";
import { withApiErrorHandling } from "@/lib/api/handler";
import { requireApiUser } from "@/lib/supabase/server";
import { parseDate } from "@/lib/api/crm";
import { canCreateProject } from "@/lib/permissions";
import { nextProjectCode } from "@/lib/api/project-code";
import { logChanges } from "@/lib/api/audit-cambios";
import { validarLineas } from "@/lib/proyectos/proyecto-general";
import {
  PROJECT_SELECT_V2,
  checkLineasExisten,
  checkMunicipiosExisten,
  checkResponsableActivo,
  normalizeProjectDate,
  projectListWhere,
  toProjectDecimal,
  toProjectItemV2,
  type ProjectListFilters,
} from "@/lib/api/projects";

export const dynamic = "force-dynamic";

const ESTADOS = Object.values(EstadoProyecto);

/** E-02 filters; an unknown `estado` is a 400 instead of an empty list. */
function parseProjectListFilters(
  url: URL,
): { ok: true; filters: ProjectListFilters } | { ok: false; response: Response } {
  const sp = url.searchParams;

  const estado = sp.get("estado") ?? undefined;
  if (estado && !ESTADOS.includes(estado as EstadoProyecto)) {
    return { ok: false, response: apiError("Estado de proyecto no válido.", 400, "VALIDATION_ERROR") };
  }

  return {
    ok: true,
    filters: {
      estado,
      cliente_id: sp.get("cliente_id") ?? undefined,
      linea_id: sp.get("linea_id") ?? undefined,
      municipio_id: sp.get("municipio_id") ?? undefined,
      responsable_id: sp.get("responsable_id") ?? undefined,
    },
  };
}

export const GET = withApiErrorHandling(
  "projects",
  "No pudimos cargar los proyectos. Inténtalo de nuevo.",
  async (request: Request) => {
    const auth = await requireApiUser();
    if (!auth.ok) return auth.response;

    const parsed = parseProjectListFilters(new URL(request.url));
    if (!parsed.ok) return parsed.response;

    const rows = await db.proyecto.findMany({
      where: projectListWhere(auth.usuario, parsed.filters),
      orderBy: { codigo: "asc" },
      select: PROJECT_SELECT_V2,
    });

    return NextResponse.json({ proyectos: rows.map(toProjectItemV2) });
  },
);

const INVALID_DATE_MESSAGES = {
  fecha_inicio: "La fecha de inicio no es válida.",
  fecha_fin: "La fecha de fin no es válida.",
} as const;

/** Fields both creation paths (E-03 and E-05) share. */
const PROJECT_CREATE_BASE = {
  responsable_id: z.string().min(1, "El responsable no puede estar vacío."),
  lineas: z
    .array(
      z.object({
        id: z.string().min(1, "La línea estratégica no es válida."),
        principal: z.boolean().optional(),
      }),
    )
    .min(1, "Selecciona al menos una línea estratégica."),
  municipio_ids: z
    .array(z.string().min(1, "El municipio no es válido."))
    .min(1, "Selecciona al menos un municipio.")
    .refine((ids) => new Set(ids).size === ids.length, "No repitas el mismo municipio."),
  fecha_inicio: z
    .string()
    .refine((value) => parseDate(value) !== null, INVALID_DATE_MESSAGES.fecha_inicio),
  fecha_fin: z
    .string()
    .refine((value) => parseDate(value) !== null, INVALID_DATE_MESSAGES.fecha_fin),
  // Upper bounds match the columns: `numeric(15,2)` and `int4`. Without them a
  // bigger number reaches Postgres and Prisma raises P2020 (ValueOutOfRange),
  // which would surface as a 500 instead of a 400.
  valor_total: z
    .number()
    .min(0, "El valor total no puede ser negativo.")
    .max(9_999_999_999_999.99, "El valor total es demasiado alto.")
    .nullable()
    .optional(),
  beneficiarios_meta: z
    .number()
    .int("La meta de beneficiarios debe ser un número entero.")
    .min(0, "La meta de beneficiarios no puede ser negativa.")
    .max(2_147_483_647, "La meta de beneficiarios es demasiado alta.")
    .nullable()
    .optional(),
} as const;

export const PROJECT_CREATE_SCHEMA = z.object({
  nombre: z
    .string()
    .trim()
    .min(1, "El nombre no puede estar vacío.")
    .max(200, "El nombre es muy largo."),
  cliente_id: z.string().min(1, "El cliente no es válido."),
  ...PROJECT_CREATE_BASE,
});

/**
 * E-05 shares the E-03 body minus `cliente_id` (derived from the URL) and with
 * `nombre` optional: the server prefills it from the opportunity when the
 * client omits it, and an explicit value overrides the prefill.
 */
export const PROJECT_CREATE_FROM_OPPORTUNITY_SCHEMA = z.object({
  nombre: z
    .string()
    .trim()
    .min(1, "El nombre no puede estar vacío.")
    .max(200, "El nombre es muy largo.")
    .optional(),
  ...PROJECT_CREATE_BASE,
});

/**
 * Fields that must not be settable at creation: `miembro_ids` belongs to S2.6,
 * `codigo` to S2.2, `estado`/`oportunidad_id`/`deleted_at` are derived, and
 * `umbrales_override`/`programacion_pendiente`/`diferencia_valor_oportunidad`/
 * `alertas` to later units. E-05 adds `cliente_id` (derived from the URL).
 */
export const PROJECT_CREATE_FORBIDDEN_FIELDS = [
  "codigo",
  "estado",
  "oportunidad_id",
  "deleted_at",
  "umbrales_override",
  "programacion_pendiente",
  "diferencia_valor_oportunidad",
  "alertas",
  "miembro_ids",
] as const;

export const PROJECT_CREATE_FROM_OPPORTUNITY_FORBIDDEN_FIELDS = [
  ...PROJECT_CREATE_FORBIDDEN_FIELDS,
  "cliente_id",
] as const;

export const POST = withApiErrorHandling(
  "projects",
  "No pudimos crear el proyecto. Inténtalo de nuevo.",
  async (request: Request) => {
    const auth = await requireApiUser();
    if (!auth.ok) return auth.response;

    if (!canCreateProject(auth.usuario)) {
      return apiError("No tienes permisos para crear proyectos.", 403, "FORBIDDEN");
    }

    const body = await parseJsonBody<Record<string, unknown>>(request);
    // A syntactically valid JSON scalar (`"x"`, 42, false) is not a body:
    // `field in body` would throw on a primitive and surface as 500, not 400.
    if (body === null || typeof body !== "object") {
      return apiError("Cuerpo de la solicitud no válido.", 400, "VALIDATION_ERROR");
    }
    for (const field of PROJECT_CREATE_FORBIDDEN_FIELDS) {
      if (field in body) {
        return apiError(
          `El campo '${field}' no se puede establecer en este endpoint.`,
          400,
          "VALIDATION_ERROR",
        );
      }
    }

    const parsed = PROJECT_CREATE_SCHEMA.safeParse(body);
    if (!parsed.success) {
      return apiError(
        parsed.error.issues[0]?.message ?? "Datos no válidos.",
        400,
        "VALIDATION_ERROR",
      );
    }

    const validacion = validarLineas(parsed.data.lineas);
    if (!validacion.ok) {
      return apiError(validacion.message, 400, "VALIDATION_ERROR");
    }

    const inicio = normalizeProjectDate(parsed.data.fecha_inicio);
    const fin = normalizeProjectDate(parsed.data.fecha_fin);
    if (fin.getTime() < inicio.getTime()) {
      return apiError(
        "La fecha de fin no puede ser anterior a la de inicio.",
        400,
        "VALIDATION_ERROR",
      );
    }

    const cliente = await db.cliente.findFirst({
      where: { id: parsed.data.cliente_id, deleted_at: null },
      select: { id: true },
    });
    if (!cliente) {
      return apiError("El cliente no existe.", 404, "NOT_FOUND");
    }

    // V-04: a suspended catalog row must not be offered to a new project. The
    // PATCH route deliberately keeps the existence-only default (REQ-CAT-02).
    const missingLineas = await checkLineasExisten(parsed.data.lineas, { onlyActive: true });
    if (missingLineas) return missingLineas;
    const missingMunicipios = await checkMunicipiosExisten(parsed.data.municipio_ids, {
      onlyActive: true,
    });
    if (missingMunicipios) return missingMunicipios;
    const inactiveResponsable = await checkResponsableActivo(parsed.data.responsable_id);
    if (inactiveResponsable) return inactiveResponsable;

    // REQ-ORG-05: the code year is the creation instant in UTC; the counter is
    // per year, so a project created on 2026-01-01T00:00Z is PRY-2026-NNN.
    const year = new Date().getUTCFullYear();

    const row = await db.$transaction(async (tx) => {
      const codigo = await nextProjectCode(tx, year);
      const created = await tx.proyecto.create({
        data: {
          codigo,
          nombre: parsed.data.nombre,
          cliente_id: parsed.data.cliente_id,
          oportunidad_id: null,
          responsable_id: parsed.data.responsable_id,
          origen: "INDEPENDIENTE",
          fecha_inicio: inicio,
          fecha_fin: fin,
          valor_total: toProjectDecimal(parsed.data.valor_total ?? null),
          beneficiarios_meta: parsed.data.beneficiarios_meta ?? null,
          lineas: {
            create: parsed.data.lineas.map((linea) => ({
              linea_id: linea.id,
              principal: linea.principal === true,
            })),
          },
          municipios: {
            create: parsed.data.municipio_ids.map((municipio_id) => ({ municipio_id })),
          },
        },
        select: PROJECT_SELECT_V2,
      });

      await logChanges(tx, [
        {
          usuario_id: auth.usuario.id,
          accion: "CREAR",
          entidad: "proyecto",
          entidad_id: created.id,
          proyecto_id: created.id,
          valor_nuevo: {
            codigo,
            nombre: parsed.data.nombre,
            cliente_id: parsed.data.cliente_id,
            origen: "INDEPENDIENTE",
          },
        },
      ]);

      return created;
    });

    return NextResponse.json({ proyecto: toProjectItemV2(row) }, { status: 201 });
  },
);
